#[oracle(utilityGetKeyValidationRequest)]
unconstrained fn get_key_validation_request_oracle(
    _pk_m_hash: Field,
    _key_index: Field,
) -> KeyValidationRequest {}

pub unconstrained fn get_key_validation_request(
    pk_m_hash: Field,
